package vn.thiendao.viethoa;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.view.*;import android.widget.*;import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.*;import com.google.mlkit.vision.text.chinese.ChineseTextRecognizerOptions;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import com.google.mlkit.nl.translate.*;import java.nio.ByteBuffer;
public class ScreenService extends Service {
 WindowManager wm; LinearLayout panel,result; ImageReader reader; MediaProjection projection; VirtualDisplay display; TextRecognizer ocr; Translator translator; Handler h=new Handler(Looper.getMainLooper()); boolean ready,busy,closed; int w,ht,dpi; TextView status;
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(i==null||projection!=null){if(i==null)stopSelf();return START_NOT_STICKY;}try{NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("screen","Dịch màn hình",NotificationManager.IMPORTANCE_LOW));Intent stop=new Intent(this,ScreenService.class).setAction("stop");PendingIntent pi=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_IMMUTABLE);startForeground(8,new Notification.Builder(this,"screen").setSmallIcon(android.R.drawable.ic_menu_view).setContentTitle("Việt Hóa đang hoạt động").setContentText("Chỉ dịch khi bạn bấm nút").addAction(new Notification.Action.Builder(null,"Dừng",pi).build()).build());wm=getSystemService(WindowManager.class);android.util.DisplayMetrics dm=new android.util.DisplayMetrics();wm.getDefaultDisplay().getRealMetrics(dm);w=dm.widthPixels;ht=dm.heightPixels;dpi=dm.densityDpi;MediaProjectionManager m=getSystemService(MediaProjectionManager.class);projection=m.getMediaProjection(i.getIntExtra("code",0),i.getParcelableExtra("data"));projection.registerCallback(new MediaProjection.Callback(){public void onStop(){stopSelf();}},h);reader=ImageReader.newInstance(w,ht,PixelFormat.RGBA_8888,2);reader.setOnImageAvailableListener(r->{try(Image image=r.acquireLatestImage()){}catch(Exception e){}},h);display=projection.createVirtualDisplay("VietHoa",w,ht,dpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,h);boolean cn=i.getBooleanExtra("chinese",true);ocr=cn?TextRecognition.getClient(new ChineseTextRecognizerOptions.Builder().build()):TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);translator=Translation.getClient(new TranslatorOptions.Builder().setSourceLanguage(cn?TranslateLanguage.CHINESE:TranslateLanguage.ENGLISH).setTargetLanguage(TranslateLanguage.VIETNAMESE).build());showPanel();translator.downloadModelIfNeeded().addOnSuccessListener(v->{ready=true;status.setText("Sẵn sàng");}).addOnFailureListener(e->status.setText("Lỗi tải mô hình; mở lại ứng dụng"));}catch(Exception e){Toast.makeText(this,"Không thể bắt đầu dịch: "+e.getMessage(),1).show();stopSelf();}return START_NOT_STICKY;}
 WindowManager.LayoutParams p(int width,int height){return new WindowManager.LayoutParams(width,height,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);}
 Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());return b;}
 void showPanel(){panel=new LinearLayout(this);panel.setOrientation(1);panel.setBackgroundColor(0xee10182d);status=new TextView(this);status.setTextColor(-1);status.setText("Đang tải mô hình…");panel.addView(status);panel.addView(btn("🇻🇳 Dịch",()->capture()));panel.addView(btn("Đóng",()->stopSelf()));WindowManager.LayoutParams lp=p(-2,-2);lp.gravity=Gravity.TOP|Gravity.LEFT;lp.y=200;status.setOnTouchListener(new View.OnTouchListener(){float x,y;int a,b;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==0){x=e.getRawX();y=e.getRawY();a=lp.x;b=lp.y;return true;}if(e.getAction()==2){lp.x=a+(int)(e.getRawX()-x);lp.y=b+(int)(e.getRawY()-y);wm.updateViewLayout(panel,lp);return true;}return true;}});wm.addView(panel,lp);}
 void capture(){if(!ready||busy)return;busy=true;clearResult();panel.setVisibility(View.INVISIBLE);reader.setOnImageAvailableListener(null,null);h.postDelayed(()->{if(closed)return;Bitmap b=null;try(Image im=reader.acquireLatestImage()){if(im==null)throw new Exception("Không có ảnh");Image.Plane pl=im.getPlanes()[0];int stride=pl.getRowStride()/pl.getPixelStride();Bitmap pad=Bitmap.createBitmap(stride,ht,Bitmap.Config.ARGB_8888);pad.copyPixelsFromBuffer(pl.getBuffer());b=Bitmap.createBitmap(pad,0,0,w,ht);if(b!=pad)pad.recycle();}catch(Exception e){finish("Không chụp được màn hình");return;}final Bitmap bitmap=b;ocr.process(InputImage.fromBitmap(bitmap,0)).addOnSuccessListener(t->{bitmap.recycle();String s=t.getText();if(s.trim().isEmpty()){finish("Không tìm thấy chữ");return;}translator.translate(s).addOnSuccessListener(this::finish).addOnFailureListener(e->finish("Dịch thất bại"));}).addOnFailureListener(e->{bitmap.recycle();finish("Nhận diện thất bại");});},450);}
 void finish(String s){if(closed)return;busy=false;reader.setOnImageAvailableListener(r->{try(Image im=r.acquireLatestImage()){}catch(Exception e){}},h);panel.setVisibility(View.VISIBLE);clearResult();result=new LinearLayout(this);result.setOrientation(1);result.setPadding(24,24,24,24);result.setBackgroundColor(0xf510182d);TextView t=new TextView(this);t.setText(s);t.setTextColor(-1);t.setTextSize(17);t.setTextIsSelectable(true);ScrollView sc=new ScrollView(this);sc.addView(t);result.addView(sc,new LinearLayout.LayoutParams(-1,0,1));result.addView(btn("Đóng bản dịch",()->clearResult()));WindowManager.LayoutParams lp=p((int)(w*.88),(int)(ht*.55));lp.gravity=Gravity.CENTER;wm.addView(result,lp);}
 void clearResult(){if(result!=null){wm.removeView(result);result=null;}}
 public void onDestroy(){closed=true;h.removeCallbacksAndMessages(null);clearResult();if(panel!=null)wm.removeView(panel);if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();if(ocr!=null)ocr.close();if(translator!=null)translator.close();super.onDestroy();}
}